mapper.sql:
where 1=1

		and crit_llave = #{llaveTabla}


		and crit_estado = #{estado}


		and crit_propiedad = #{propiedad}


		and crit_plantilla = #{plantilla}


		and crit_campo = #{campo}


		and crit_auxiliar = #{auxiliar}


		and drit_fechainicio >= #{fechaInicioMin}


		and drit_fechainicio  <   #{fechaInicioMax}


		and crit_usuariocreacion = #{usuarioCreacion}


		and crit_usuarioeliminacion = #{usuarioEliminacion}

mapper.select:
select  cdpc_plantilla 
from documentoplantillacaracteristica_dpcp
where cdpc_llave = #{pFieldId}

update propiedad_ppdp 
set nppd_relaciones = (select count(*) from relacioninterna_ritp rr where rr.crit_propiedad = cppd_llave and rr.crit_estado = 'A')
where cppd_estado = 'A' and cppd_llave = #{pProperty}
